"""
Pages Batch 6 (Canvases 63-67, pp. 25-29) for Wellcome MS.244.
Covers medical & surgical receipts on pp. 25-29:
  - Canvas 63 (p. 25): Fistula remedies (internal potions, hellebore, sucking whelp, Stooks, Hall's powder)
  - Canvas 64 (p. 26): Especial Note on hard tents (Dec 1612), tent/plaster & incised quill diagrams, beef-sinew probe, Master Arderne's green ointment, 1616 tent note
  - Canvas 65 (p. 27): Fistula case (May 1616), De Colubrina, Balsamum Sulphuris, whalebone 'thumb' probe, sponge tent, Stockerus's human-dung water (1619-1620), two margin manicules
  - Canvas 66 (p. 28): Tents & ointments for fistulas and impostumes (Phioravanti), Sore Breast, Sanativum Mirabile (Weapon Salve)
  - Canvas 67 (p. 29): Breastes (red-lead black plaster, dog-dung styptic, oil of mallows from grandmother Eliz. S., cataplasm, 'y^e tent made' / 'the tente vn made' diagrams)
"""


def make_lines(prefix, canvas_num, col_id, ulx, uly, lrx, lry, line_tuples):
    n = len(line_tuples)
    step = (lry - uly) / max(1, n)
    img_svc = f"https://iiif.wellcomecollection.org/image/b19608652_MS_244_{canvas_num:04d}.JP2"
    canvas_uri = f"https://iiif.wellcomecollection.org/presentation/b19608652/canvases/b19608652_MS_244_{canvas_num:04d}.JP2"
    out = []
    for idx, (lno, ltype, orig_text, en_text, note) in enumerate(line_tuples):
        y0 = int(round(uly + idx * step))
        y1 = int(round(uly + (idx + 1) * step))
        w = lrx - ulx
        h = y1 - y0
        xywh = f"{ulx},{y0},{w},{h}"
        line_id = f"{prefix}_{col_id}_l{lno:02d}" if isinstance(lno, int) else f"{prefix}_{col_id}_{lno}"
        out.append({
            "line_id": line_id,
            "line_num": str(lno),
            "line_type": ltype,
            "ulx": ulx,
            "uly": y0,
            "lrx": lrx,
            "lry": y1,
            "xywh": xywh,
            "iiif_canvas_xywh": f"{canvas_uri}#xywh={xywh}",
            "iiif_image_crop": f"{img_svc}/{xywh}/full/0/default.jpg",
            "orig": orig_text,
            "en": en_text,
            "note": note,
        })
    return out


